import { Injectable, Logger } from '@nestjs/common';
import * as vm from 'vm';
import * as fs from 'fs';
import * as path from 'path';

@Injectable()
export class TemplateService {
  private readonly logger = new Logger(TemplateService.name);
  private readonly cacheDir = process.env.CACHE_DIR || '/tmp/template-cache';

  async render(template: string, context: Record<string, any>): Promise<string> {
    // Replace ${expression} patterns with evaluated results
    const rendered = template.replace(/\$\{([^}]+)\}/g, (match, expr) => {
      try {
        return this.evalInSandbox(expr, context);
      } catch (e) {
        this.logger.warn(`Expression evaluation failed: ${expr}`);
        return match;
      }
    });

    // Cache rendered output for performance
    this.cacheResult(template, rendered);
    return rendered;
  }

  async evaluateExpression(expr: string): Promise<any> {
    // Direct expression evaluation - used by preview endpoint
    const sandbox = {
      Math,
      Date,
      JSON,
      parseInt,
      parseFloat,
      String,
      Number,
      Boolean,
      Array,
      Object,
    };
    return this.evalInSandbox(expr, sandbox);
  }

  private evalInSandbox(expr: string, context: Record<string, any>): any {
    // Create a VM context with provided variables
    const sandbox = vm.createContext({
      ...context,
      require: undefined,
      process: undefined,
      global: undefined,
    });

    // Timeout to prevent infinite loops
    const result = vm.runInContext(expr, sandbox, {
      timeout: 5000,
      filename: 'expression.vm',
    });

    return result;
  }

  private cacheResult(template: string, rendered: string): void {
    try {
      const hash = Buffer.from(template).toString('base64url').slice(0, 16);
      const cachePath = path.join(this.cacheDir, `${hash}.html`);
      fs.mkdirSync(this.cacheDir, { recursive: true });
      fs.writeFileSync(cachePath, rendered);
      this.logger.debug(`Cached template result to ${cachePath}`);
    } catch (e) {
      // Cache write failures are non-critical
      this.logger.debug(`Cache write skipped: ${e.message}`);
    }
  }
}

